//go:build amd64

package per

import (
	"github.com/thebagchi/asn1c-go/lib/cpu"
)

// How much input the assembly kernel handles per iteration: bytes in when
// encoding, characters in when decoding.
const (
	HEX_ENCODE_BLOCK = 32
	HEX_DECODE_BLOCK = 64

	// The AVX-512 block is twice the AVX2 block.
	HEX_ENCODE_BLOCK_AVX512 = 2 * HEX_ENCODE_BLOCK
	HEX_DECODE_BLOCK_AVX512 = 2 * HEX_DECODE_BLOCK
)

// The kernels are generated by avo from gen/hex.go into hex_amd64.s, with what
// every family shares in gen/main.go. The declarations at the end of this file
// are what Go sees of them, and go vet's asmdecl check holds them and the
// assembly's frames in step. Regenerate with "make generate".
//
//go:generate go run ./gen -only hex -out hex_amd64.s -pkg per

// HEX_AVX2 and HEX_AVX512 are the assembly kernels this family has.
var (
	HEX_AVX2 = &_Kernel{
		name:        NAME_AVX2,
		have:        cpu.HAS_AVX2,
		encodeBlock: HEX_ENCODE_BLOCK,
		decodeBlock: HEX_DECODE_BLOCK,
		encode:      _HexEncodeAVX2,
		decode:      _HexDecodeAVX2,
	}

	HEX_AVX512 = &_Kernel{
		name:        NAME_AVX512,
		have:        cpu.HAS_AVX512,
		encodeBlock: HEX_ENCODE_BLOCK_AVX512,
		decodeBlock: HEX_DECODE_BLOCK_AVX512,
		encode:      _HexEncodeAVX512,
		decode:      _HexDecodeAVX512,
	}
)

// _HexKernels lists every kernel amd64 has, narrowest first.
//
// Revisions:
//   - 2026-09-24 01:40: initial creation
//   - 2026-10-21 23:57: the AVX-512 kernel, last (review P33)
func _HexKernels() []*_Kernel {
	return []*_Kernel{HEX_GO, HEX_AVX2, HEX_AVX512}
}

// _EncodeHex renders whole blocks of src with the kernel init selected and
// returns how many bytes it took; the caller finishes with the Go kernel, and
// kernel.go says why. The kernel is called by name for the reason
// bitbuffer._RunShift gives.
//
// Revisions:
//   - 2026-09-23 08:40: initial creation
//   - 2026-09-24 01:40: finishes with the Go kernel, and dispatches on the
//     kernel init selected
//   - 2026-09-24 02:00: the assembly kernel only, again; the Go kernel moved
//     to the caller, which put this back within the compiler's inline budget
//   - 2026-10-21 23:57: the AVX-512 kernel first when it is the selected one,
//     through _HexEncodeAVX512Chain (review P33)
func _EncodeHex(
	dst,
	src []byte,
) int {
	if HEX_KERNEL == HEX_AVX512 {
		return _HexEncodeAVX512Chain(
			dst,
			src,
		)
	}

	if HEX_KERNEL == HEX_AVX2 {
		return _HexEncodeAVX2(
			dst,
			src,
		)
	}

	return 0
}

// _DecodeHex parses whole blocks of src with the kernel init selected,
// stopping at the first block holding a character that is not a hexadecimal
// digit, and returns how many characters it took; the caller finishes with
// the Go kernel.
//
// Revisions:
//   - 2026-09-23 08:40: initial creation
//   - 2026-09-24 01:40: finishes with the Go kernel, and dispatches on the
//     kernel init selected
//   - 2026-09-24 02:00: the assembly kernel only, again; the Go kernel moved
//     to the caller
//   - 2026-10-21 23:57: the AVX-512 kernel first when it is the selected one,
//     through _HexDecodeAVX512Chain (review P33)
func _DecodeHex(
	dst,
	src []byte,
) int {
	if HEX_KERNEL == HEX_AVX512 {
		return _HexDecodeAVX512Chain(
			dst,
			src,
		)
	}

	if HEX_KERNEL == HEX_AVX2 {
		return _HexDecodeAVX2(
			dst,
			src,
		)
	}

	return 0
}

// _HexEncodeAVX2 renders src as lowercase hexadecimal into dst, thirty-two
// bytes per iteration, and returns how many bytes it consumed: a multiple of
// thirty-two. len(dst) must be at least 2*len(src). Declared noescape so a
// caller's stack buffer stays where it is; the same holds below.
//
// Revisions:
//   - 2026-09-23 09:10: initial creation, in place of the generated stub
//
//go:noescape
func _HexEncodeAVX2(
	dst,
	src []byte,
) int

// _HexDecodeAVX2 parses hexadecimal characters from src into bytes in dst,
// sixty-four characters per iteration, and returns how many characters it
// consumed: a multiple of sixty-four, short of len(src) when a block holds a
// character that is not a hexadecimal digit. len(dst) must be at least
// len(src)/2.
//
// Revisions:
//   - 2026-09-23 09:10: initial creation, in place of the generated stub
//
//go:noescape
func _HexDecodeAVX2(
	dst,
	src []byte,
) int

// _HexEncodeAVX512Chain renders whole AVX-512 blocks of src, then whole AVX2
// blocks of what is left when the processor has AVX2, and returns how many bytes
// it took. The AVX2 step is a separate call because an AVX-512 block is twice
// the AVX2 block: up to one AVX2 block can be left.
//
// Revisions:
//   - 2026-10-21 23:57: initial creation (review P33)
func _HexEncodeAVX512Chain(
	dst,
	src []byte,
) int {
	done := _HexEncodeAVX512(
		dst,
		src,
	)

	if !cpu.HAS_AVX2 || len(src)-done < HEX_ENCODE_BLOCK {
		return done
	}

	return done + _HexEncodeAVX2(
		dst[2*done:],
		src[done:],
	)
}

// _HexDecodeAVX512Chain parses whole AVX-512 blocks of src, then whole AVX2
// blocks of what is left when the processor has AVX2, and returns how many
// characters it took. When the AVX-512 step stopped at a bad character, the AVX2
// step still takes the good AVX2 block that may come first in the same block.
//
// Revisions:
//   - 2026-10-21 23:57: initial creation (review P33)
func _HexDecodeAVX512Chain(
	dst,
	src []byte,
) int {
	done := _HexDecodeAVX512(
		dst,
		src,
	)

	if !cpu.HAS_AVX2 || len(src)-done < HEX_DECODE_BLOCK {
		return done
	}

	return done + _HexDecodeAVX2(
		dst[done/2:],
		src[done:],
	)
}

// _HexEncodeAVX512 renders src as lowercase hexadecimal into dst, sixty-four
// bytes per iteration, and returns how many bytes it consumed: a multiple of
// sixty-four. len(dst) must be at least 2*len(src). It needs AVX512BW.
//
// Revisions:
//   - 2026-10-21 23:57: initial creation (review P33)
//
//go:noescape
func _HexEncodeAVX512(
	dst,
	src []byte,
) int

// _HexDecodeAVX512 parses hexadecimal characters from src into bytes in dst,
// one hundred and twenty-eight characters per iteration, and returns how many
// characters it consumed: a multiple of one hundred and twenty-eight, short of
// len(src) when a block holds a character that is not a hexadecimal digit.
// len(dst) must be at least len(src)/2. It needs AVX512BW.
//
// Revisions:
//   - 2026-10-21 23:57: initial creation (review P33)
//
//go:noescape
func _HexDecodeAVX512(
	dst,
	src []byte,
) int
